import type { PersonInput } from "@/lib/schema";

/**
 * People: leading clinicians and scientists at US East Coast / Midwest centres and Toronto.
 * Public professional information only (institutional roles, publications, professional profiles).
 * Roles are as publicly reported up to 2026-09; people move, so `role` should be re-checked periodically.
 */
const asOf = "2026-09-08";
const pubmed = (q: string) => ({ label: "PubMed", url: `https://pubmed.ncbi.nlm.nih.gov/?term=${encodeURIComponent(q)}%5BAuthor%5D` });
const doi = (title: string, journal: string, year: number, d: string, note?: string) => ({ title, journal, year, doi: d, url: `https://doi.org/${d}`, note });
const paper = (title: string, journal: string, year: number, note?: string) => ({ title, journal, year, note });

type P = Omit<PersonInput, "kind" | "asOf"> & { institutionId: string };
const p = (x: P): PersonInput => ({ kind: "person", asOf, institutions: [x.institutionId], ...x });

